#include <bits/stdc++.h>
using namespace std;
const int mod = 1e9 + 7;
int n, m, res;
int solve() {
    res = 1;
    if (!m) {
        int i = 1;
        while (i < n) {
            res = 1LL * res * n % mod;
            ++i;
        }
    } else if (m == 1) {
        int i = 1;
        while (i <= n) {
            res = 1LL * res * n % mod;
            ++i;
        }
    } else {
        vector<int> seen(n, 0);
        for (int i = 0; i < n; ++i) {
            if (!seen[i]) {
                int len = 0;
                int cur = i;
                while (!seen[cur]) {
                    seen[cur] = 1;
                    ++len;
                    cur = 1LL * cur * m % n;
                }
                if (cur != 0)
                    res = 1LL * res * n % mod;
            }
        }
    }
    return res;
}
int32_t main() {
#ifndef ONLINE_JUDGE
    freopen("data", "r", stdin);
#endif
    cin >> n >> m;
    cout << solve();
    return 0;
}
